PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE households (
        id INTEGER PRIMARY KEY,
        name TEXT NOT NULL UNIQUE,
        created_at INTEGER NOT NULL
    );
INSERT INTO households VALUES(1,'Home',1793185778);
CREATE TABLE users (
        id INTEGER PRIMARY KEY,
        household_id INTEGER NOT NULL REFERENCES households(id),
        name TEXT NOT NULL UNIQUE COLLATE NOCASE,
        display_name TEXT NOT NULL,
        -- NULL until the person has set a password through their invite.
        pw_hash TEXT,
        is_admin INTEGER NOT NULL DEFAULT 0,
        created_at INTEGER NOT NULL
    );
INSERT INTO users VALUES(1,1,'alice','Alice','$argon2id$v=19$m=19456,t=2,p=1$YH1etN7ibgEe2yEf/ojE+g$DNvxgjNiXgUiZqhidf91iHTUC0MeKiAsrrmK/AIcYFM',1,1793185778);
INSERT INTO users VALUES(2,1,'bob','Bob','$argon2id$v=19$m=19456,t=2,p=1$IksDkMT27XqrhpxVH1jc5A$la5ihYKYzc7O/hH9tjisomYUFJEaxxIqI2UemyVmHdo',0,1793185778);
CREATE TABLE sessions (
        token_sha256 TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        created_at INTEGER NOT NULL,
        last_seen_at INTEGER NOT NULL
    );
INSERT INTO sessions VALUES('f034d770498ae386b643a421fa339dabe73603a4ec5263add43f70f6781173f6',1,1793185778,1793185778);
INSERT INTO sessions VALUES('04f4d2003f101b52418150581a5b95815f57085372cddbebbb6e9ff0050fd04d',2,1793185778,1793185778);
CREATE TABLE invites (
        token_sha256 TEXT PRIMARY KEY,
        household_id INTEGER NOT NULL REFERENCES households(id),
        name TEXT NOT NULL,
        is_admin INTEGER NOT NULL DEFAULT 0,
        user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,
        created_at INTEGER NOT NULL,
        expires_at INTEGER NOT NULL,
        used_at INTEGER
    );
INSERT INTO invites VALUES('7fef112e746f611d7fc598e3f0c9c46fbf3cebdbc34e9078c3a5a16179e7a8f7',1,'alice',1,NULL,1793185778,1793790578,1793185778);
INSERT INTO invites VALUES('60f162d6fe4831619835aaefa755b4e3852fc56b2380701070758184c1676b42',1,'bob',0,NULL,1793185778,1793790578,1793185778);
CREATE TABLE cards (
        id INTEGER PRIMARY KEY,
        household_id INTEGER NOT NULL REFERENCES households(id),
        holder_user_id INTEGER REFERENCES users(id),
        private INTEGER NOT NULL DEFAULT 0 CHECK (private = 0 OR holder_user_id IS NOT NULL),
        name TEXT NOT NULL,
        program TEXT NOT NULL DEFAULT '',
        code_value TEXT NOT NULL,
        code_format TEXT NOT NULL,
        display_number TEXT NOT NULL DEFAULT '',
        color TEXT NOT NULL,
        notes TEXT NOT NULL DEFAULT '',
        use_count INTEGER NOT NULL DEFAULT 0,
        last_used_at INTEGER,
        created_at INTEGER NOT NULL,
        updated_at INTEGER NOT NULL
    );
INSERT INTO cards VALUES(1,1,NULL,0,'Supermarket','Club','4006381333931','ean13','','#c2291e','The family card',0,NULL,1793185778,1793185778);
INSERT INTO cards VALUES(2,1,2,1,'Airline','','MILES-0042','code128','0042','#1c7455','',0,NULL,1793185792,1793185792);
CREATE TABLE blobs (
        sha256 TEXT PRIMARY KEY,
        mime TEXT NOT NULL,
        bytes BLOB NOT NULL
    );
INSERT INTO blobs VALUES('59418b23740b9c14a74ac7975e07efbed947f1f30ce25aff01e23db0c8cabd36','image/png',x'');
CREATE TABLE photos (
        card_id INTEGER NOT NULL REFERENCES cards(id) ON DELETE CASCADE,
        side TEXT NOT NULL CHECK (side IN ('front', 'back')),
        sha256 TEXT NOT NULL REFERENCES blobs(sha256),
        PRIMARY KEY (card_id, side)
    );
INSERT INTO photos VALUES(1,'front','59418b23740b9c14a74ac7975e07efbed947f1f30ce25aff01e23db0c8cabd36');
CREATE INDEX cards_by_household ON cards(household_id);
CREATE INDEX photos_by_blob ON photos(sha256);
COMMIT;
PRAGMA user_version=1;
